  d = min(d, seg(p, vec2(1.05, 0.92), vec2(1.025, 1.13), 0.006, 0.004));
  d = min(d, seg(p, vec2(1.07, 0.92), vec2(1.09, 1.15), 0.006, 0.004));
  d = min(d, seg(p, vec2(1.09, 0.92), vec2(1.15, 1.1), 0.006, 0.004));
  d = min(d, box(p, vec2(0.93, 0.825), vec2(0.03, 0.025)));
  d = min(d, box(p, vec2(0.36, 0.81), vec2(0.06, 0.012)));
